import json, sys
from pathlib import Path
# Print the human's prompts and the assistant's final text replies, in order.
path = Path(sys.argv[1])
limit = int(sys.argv[2]) if len(sys.argv) > 2 else 1500
for n, line in enumerate(path.open(encoding="utf-8", errors="replace"), 1):
    try:
        e = json.loads(line)
    except ValueError:
        continue
    if not isinstance(e, dict):
        continue
    msg = e.get("message") if isinstance(e.get("message"), dict) else {}
    c = msg.get("content")
    if e.get("type") == "user" and isinstance(c, str) and not e.get("isMeta"):
        if c.lstrip().startswith("<"):
            continue
        print(f"\n### L{n} USER:\n{c[:limit]}")
    elif e.get("type") == "user" and isinstance(c, list):
        for b in c:
            if isinstance(b, dict) and b.get("type") == "text" and not b.get("text","").lstrip().startswith("<"):
                print(f"\n### L{n} USER(text block):\n{b['text'][:limit]}")
    elif e.get("type") == "assistant" and isinstance(c, list):
        texts = [b.get("text","") for b in c if isinstance(b, dict) and b.get("type") == "text"]
        t = "\n".join(x for x in texts if x.strip())
        if t.strip():
            print(f"\n--- L{n} ASSISTANT:\n{t[:limit]}")
EOF
